def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: (x[0], x[1]))
    merged = []
    for interval in sorted_intervals:
        if not merged or merged[-1][1] < interval[0]:
            merged.append([interval[0], interval[1]])
        else:
            merged[-1][1] = max(merged[-1][1], interval[1])
    return merged

import heapq


def toposort(nodes, edges):
    adj = {n: set() for n in nodes}
    in_degree = {n: 0 for n in nodes}
    seen = set()
    for src, dst in edges:
        if (src, dst) in seen:
            continue
        seen.add((src, dst))
        if src == dst:
            raise ValueError("cycle detected")
        adj[src].add(dst)
        in_degree[dst] += 1

    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0:
        raise ValueError("limit must be a positive integer")
    for _, weight in items:
        if not isinstance(weight, int) or isinstance(weight, bool) or weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
    batches = []
    current_batch = []
    current_weight = 0
    for name, weight in items:
        if current_weight + weight <= limit:
            current_batch.append(name)
            current_weight += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_weight = weight
    if current_batch:
        batches.append(current_batch)
    return batches

import re

def parse_env(text):
    result = {}
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid environment assignment: {line!r}")
        key, _, value = line.partition('=')
        key = key.strip()
        value = value.strip()
        if not key_re.match(key):
            raise ValueError(f"Invalid environment key: {key!r}")
        if (value.startswith('"') and value.endswith('"')) or \
           (value.startswith("'") and value.endswith("'")):
            value = value[1:-1]
        result[key] = value
    return result

import math

def retry_delay(attempt, base, cap):
    if isinstance(attempt, bool) or type(attempt) is not int:
        raise ValueError("attempt must be an integer")
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if isinstance(base, bool) or not isinstance(base, (int, float)):
        raise ValueError("base must be a finite nonnegative number")
    if base < 0 or not math.isfinite(float(base)):
        raise ValueError("base must be a finite nonnegative number")
    if isinstance(cap, bool) or not isinstance(cap, (int, float)):
        raise ValueError("cap must be a finite nonnegative number")
    if cap < 0 or not math.isfinite(float(cap)):
        raise ValueError("cap must be a finite nonnegative number")

    if base == 0 or cap == 0:
        return 0.0

    base_f = float(base)
    cap_f = float(cap)

    # Determine whether base_f * 2**attempt >= cap_f without overflow.
    # base_f * 2**attempt >= cap_f  <==>  attempt >= log2(cap_f / base_f)
    log2_ratio = math.log2(cap_f / base_f)
    if attempt >= log2_ratio:
        return cap_f

    # In this branch attempt < log2(cap_f/base_f), so the true value is
    # strictly less than cap_f (finite). math.ldexp then cannot overflow.
    value = math.ldexp(base_f, attempt)
    return min(cap_f, value)

def fifo_admit(active, queued, budget, slots):
    for req in queued:
        if req > budget:
            raise ValueError("queued reservation exceeds the whole budget")

    occupied = 0
    used = 0
    for res in active:
        occupied += res
        used += 1

    admitted = []
    remaining = []
    for req in queued:
        if occupied + req <= budget and used + 1 <= slots:
            admitted.append(req)
            occupied += req
            used += 1
        else:
            remaining.append(req)

    return admitted, remaining
